def style(bg='transparent',p=0):return dict(bgType='color',bgColor=bg,marginLeft=20,marginRight=20,marginBottom=20,paddingTop=p,paddingBottom=p,paddingLeft=p,paddingRight=p,**{k:18 for k in ['borderTopLeftRadius','borderTopRightRadius','borderBottomLeftRadius','borderBottomRightRadius']})
